  return str.length > n ? str.substring(0, n) + "..." : str;
}

// 'a' shifts the emoji pairs onto an odd boundary so the default n=16 cut lands mid-pair
console.log(JSON.stringify(truncate("a" + "🎉".repeat(12))));
// -> "a🎉🎉🎉🎉🎉🎉🎉\ud83c...

